S = "Hakeem Force Academy"
QS = [
(S, "What is the status of Iran in SAARC?", ["Full member", "Observer", "Founding member", "Dialogue partner only in 1985"], 1,
 "SAARC has eight full members: Afghanistan, Bangladesh, Bhutan, India, Maldives, Nepal, Pakistan and Sri Lanka. Iran is only an observer, so it is not a member.",
 "Other SAARC observers include China, Japan, the USA, the European Union, Australia, South Korea, Mauritius and Myanmar.", 1),
(S, "Is the number pi a rational or an irrational number?", ["Rational number", "Irrational number", "Whole number", "Integer"], 1,
 "Pi cannot be written as a fraction of two integers and its decimal expansion never ends or repeats. Hence it is irrational.",
 "Fractions such as 22/7 are only approximations of pi (3.14159...).", 1),
(S, "Joe Biden, who took office in January 2021, was which President of the USA?", ["43rd", "44th", "45th", "46th"], 3,
 "Barack Obama was 44th and Donald Trump 45th, so Joe Biden who followed him was the 46th President.",
 "Donald Trump returned to office in January 2025 as the 47th President.", 1),
(S, "K2 lies on the border between Pakistan and which country?", ["India", "Afghanistan", "China", "Nepal"], 2,
 "K2 stands in the Karakoram range on the border of Gilgit-Baltistan (Pakistan) and Xinjiang (China).",
 "K2 is the second highest mountain in the world at about 8,611 m.", 1),
(S, "Lack of vitamin D causes which disease in the body?", ["Night blindness", "Scurvy", "Beriberi", "Rickets"], 3,
 "Vitamin D helps the body absorb calcium for bones. Its deficiency causes rickets in children and soft bones in adults.",
 "Sunlight helps the skin make vitamin D.", 1),
(S, "Lapels are a part of which garment?", ["Trousers", "Coat or jacket", "Socks", "Shoes"], 1,
 "A lapel is the folded flap on the front of a coat or jacket below the collar.",
 "The lapel is the part where a flower or badge is often pinned.", 1),
(S, "The rank of Lieutenant in the Pakistan Navy is equal to which rank in the Army?", ["Lieutenant", "Captain", "Major", "Second Lieutenant"], 1,
 "Navy Sub Lieutenant equals Army Lieutenant, and Navy Lieutenant equals Army Captain.",
 "Navy Lieutenant Commander equals Army Major.", 1),
(S, "Matrix A is of order 2 x 1 and matrix B is of order 1 x 2. What is the order of the product AB?", ["1 x 1", "2 x 1", "1 x 2", "2 x 2"], 3,
 "For a product the columns of A (1) equal the rows of B (1), so AB exists. Its order is rows of A by columns of B, that is 2 x 2.",
 "The product BA in this case would be of order 1 x 1.", 1),
(S, "Narendra Modi is a famous politician of which country?", ["Nepal", "Sri Lanka", "India", "Bangladesh"], 2,
 "Narendra Modi is the Prime Minister of India, leading the BJP.",
 "He has been Prime Minister since 2014 and is in his third term after the 2024 election.", 1),
(S, "Mohenjo-daro is located near which city of Sindh?", ["Hyderabad", "Larkana", "Sukkur", "Thatta"], 1,
 "Mohenjo-daro, a city of the Indus Valley Civilisation, lies in Larkana District on the right bank of the Indus.",
 "Mohenjo-daro means Mound of the Dead and it is a UNESCO World Heritage Site.", 3),
(S, "Musailma Kazzab was killed in which battle?", ["Battle of Badr", "Battle of Yamama", "Battle of Yarmuk", "Battle of Uhud"], 1,
 "Musailma, the false claimant of prophethood, was killed by Wahshi in the Battle of Yamama in 632-633 CE in the caliphate of Hazrat Abu Bakr (RA).",
 "Many Huffaz of the Quran were martyred at Yamama, which led to the compilation of the Quran.", 1),
(S, "Nanga Parbat is which highest peak of the world?", ["Fourth", "Sixth", "Ninth", "Twelfth"], 2,
 "Nanga Parbat, at 8,126 m, is the ninth highest mountain in the world.",
 "It is the second highest peak in Pakistan after K2 and is nicknamed Killer Mountain.", 1),
(S, "Nelson Mandela was the leader and later President of which country?", ["Nigeria", "Kenya", "South Africa", "Zimbabwe"], 2,
 "Mandela led the struggle against apartheid and became South Africa's first black President in 1994.",
 "He was imprisoned for 27 years and won the Nobel Peace Prize in 1993.", 1),
(S, "Night blindness is caused by the deficiency of which vitamin?", ["Vitamin A", "Vitamin B", "Vitamin C", "Vitamin K"], 0,
 "Vitamin A is needed to form the visual pigment in the eye, so its lack makes it hard to see in dim light.",
 "Carrots, spinach and liver are good sources of vitamin A.", 1),
(S, "Nuku'alofa is the capital of which country?", ["Fiji", "Samoa", "Vanuatu", "Tonga"], 3,
 "Nuku'alofa, on the island of Tongatapu, is the capital of the Kingdom of Tonga in the Pacific.",
 "Tonga is a Polynesian monarchy and has never been fully colonised.", 1),
(S, "For which achievement did Malala Yousafzai receive the Nobel Prize in 2014?", ["Literature", "Peace", "Medicine", "Economics"], 1,
 "She received the Nobel Peace Prize for her struggle for the right of children and girls to education.",
 "At 17 she is the youngest Nobel laureate in history and shared the prize with Kailash Satyarthi.", 1),
(S, "On what date did Pakistan get its first constitution?", ["14 August 1947", "23 March 1956", "12 March 1949", "8 June 1962"], 1,
 "Pakistan's first constitution was enforced on 23 March 1956 and the country became an Islamic Republic.",
 "It was abrogated by Ayub Khan's martial law on 7 October 1958 and 23 March is now Pakistan Day.", 1),
(S, "On what date was Benazir Bhutto assassinated?", ["27 December 2007", "27 December 2008", "18 October 2007", "4 April 2007"], 0,
 "She was killed in a gun and bomb attack after an election rally at Liaquat Bagh, Rawalpindi, on 27 December 2007.",
 "She was the first woman Prime Minister of a Muslim-majority country.", 1),
(S, "The Simla Conference of 1945 was held on 25 June 1945 under which Viceroy?", ["Lord Mountbatten", "Lord Linlithgow", "Lord Wavell", "Lord Irwin"], 2,
 "Viceroy Lord Wavell called the conference at Simla to discuss his plan for an Executive Council with Indian members.",
 "It failed because Congress and the Muslim League disagreed over the choice of Muslim members.", 1),
(S, "On what date was the State Bank of Pakistan established?", ["14 August 1947", "1 July 1948", "11 September 1948", "1 January 1949"], 1,
 "The State Bank of Pakistan began working on 1 July 1948 and was inaugurated by Quaid-e-Azam.",
 "Its first Governor was Zahid Hussain.", 1),
(S, "On what date did Quaid-e-Azam present his 14 Points, and in reply to which report?", ["28 March 1929, reply to the Nehru Report", "23 March 1940, reply to the Cripps Mission", "28 March 1929, reply to the Simon Report", "12 December 1930, reply to the Lahore Resolution"], 0,
 "Quaid-e-Azam Muhammad Ali Jinnah presented his 14 Points in Delhi on 28 March 1929 as an answer to the Nehru Report of 1928.",
 "The 14 Points demanded safeguards for Muslims, including separate electorates and one-third seats in the central legislature.", 1),
(S, "On which date of the Hijri month was the Last Sermon (Khutbah Hajjat-ul-Wida) of the Holy Prophet (SAW) delivered?", ["8th Dhul Hijjah", "9th Dhul Hijjah", "10th Dhul Hijjah", "12th Dhul Hijjah"], 1,
 "The sermon was delivered on 9 Dhul Hijjah, 10 AH, in the Uranah valley of Mount Arafat during the Farewell Hajj.",
 "Some people say 10th, but the standard account is the Day of Arafah, the 9th.", 1),
(S, "On which date was SAARC formed?", ["8 December 1985", "8 August 1967", "21 September 1969", "14 March 1980"], 0,
 "SAARC was established at the Dhaka summit on 8 December 1985 by seven South Asian countries.",
 "Its secretariat is in Kathmandu, Nepal, and Afghanistan joined in 2007.", 1),
(S, "According to the Quran, on which mountain did the ark of Prophet Noah (AS) come to rest?", ["Mount Sinai", "Mount Uhud", "Mount Judi", "Mount Hira"], 2,
 "Surah Hud (verse 44) says the ark settled on Al-Judi, a mountain in the Kurdistan region.",
 "The Bible names the mountains of Ararat, so sources differ.", 1),
(S, "Canada and the United States are separated mostly by which parallel of latitude?", ["38th parallel", "49th parallel", "17th parallel", "30th parallel"], 1,
 "A large part of the border between Canada and the contiguous USA follows the 49th parallel north.",
 "The 38th parallel divides North and South Korea.", 1),
(S, "On which Prophet was the Injil revealed?", ["Hazrat Musa (AS)", "Hazrat Dawood (AS)", "Hazrat Ibrahim (AS)", "Hazrat Isa (AS)"], 3,
 "The Injil (Gospel) was revealed to Hazrat Isa (AS), known as Jesus.",
 "The Zaboor was revealed to Hazrat Dawood (AS).", 1),
(S, "On which Prophet was the Taurat revealed?", ["Hazrat Musa (AS)", "Hazrat Isa (AS)", "Hazrat Dawood (AS)", "Hazrat Yaqub (AS)"], 0,
 "The Taurat (Torah) was revealed to Hazrat Musa (AS) on Mount Tur.",
 "It is one of the four major revealed books along with Zaboor, Injil and the Quran.", 1),
]
